<?php require __DIR__.'/../includes/bootstrap.php';require_auth();if(!collector_marketplace_ready())redirect('upgrade-collector-marketplace.php');$existing=collector_profile_by_user((int)user()['id']);if($existing)redirect_route('collectors/manage.php',['id'=>$existing['id']]);if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$name=trim($_POST['shop_name']??'');if($name==='')throw new RuntimeException('Shop name is required.');$status=(user()['role']??'')==='admin'?'approved':'pending';db()->prepare('INSERT INTO collector_profiles(user_id,shop_name,slug,tagline,bio,location,website,status) VALUES(?,?,?,?,?,?,?,?)')->execute([(int)user()['id'],$name,collector_slug($name),trim($_POST['tagline']??''),trim($_POST['bio']??''),trim($_POST['location']??''),trim($_POST['website']??''),$status]);redirect_route('collectors/manage.php',['id'=>(int)db()->lastInsertId()]);}catch(Throwable $e){flash('error',$e->getMessage());}}app_header('Open Collector Profile');?><section class="form-card wide"><p class="eyebrow">COLLECTOR MARKETPLACE</p><h1>Open Your Collector Profile</h1><form method="post" class="form-grid"><?=csrf_field()?><label>Shop or collector name<input name="shop_name" required></label><label>Tagline<input name="tagline"></label><label>Location<input name="location"></label><label>Website<input type="url" name="website"></label><label class="full">About your collection<textarea name="bio" rows="6"></textarea></label><button class="button primary">Create Collector Profile</button></form></section><?php app_footer();
